import{_ as a,o as t,c as s,a3 as o}from"./chunks/framework.BlfGB29P.js";const m=JSON.parse('{"title":"État de la traduction","description":"État de la documentation UIX française.","frontmatter":{"title":"État de la traduction","description":"État de la documentation UIX française."},"headers":[],"relativePath":"fr/projects/uix/translation-status.md","filePath":"fr/projects/uix/translation-status.md","lastUpdated":1793113714000}'),r={name:"fr/projects/uix/translation-status.md"};function n(i,e,c,d,l,u){return t(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="etat-de-la-traduction" tabindex="-1">État de la traduction <a class="header-anchor" href="#etat-de-la-traduction" aria-label="Permalink to &quot;État de la traduction&quot;">​</a></h1><p>Cette documentation française est maintenue à partir de la documentation UIX canonique en anglais. Les pages principales, le démarrage rapide et les aperçus de UIX Styling, Forge, Broker et Extras sont déjà disponibles en français. La section complète <strong>UIX Broker</strong> est également disponible en français.</p><h2 id="verification-du-contenu-du-26-octobre-2026" tabindex="-1">Vérification du contenu du 26 octobre 2026 <a class="header-anchor" href="#verification-du-contenu-du-26-octobre-2026" aria-label="Permalink to &quot;Vérification du contenu du 26 octobre 2026&quot;">​</a></h2><p>Les <strong>64 pages canoniques</strong> ont été vérifiées à nouveau avec la <a href="https://github.com/Lint-Free-Technology/uix/tree/26e54e6d4973231a393933e6479ed1b03cc86cd3/docs/source" target="_blank" rel="noreferrer">source anglaise <code>26e54e6</code></a>. La branche <code>dev</code> n’a pas changé depuis la revue précédente ; le site original indique toujours <strong>9.0.0-beta.2</strong>. La base stable reste <strong>8.4.0</strong>.</p><ul><li><strong>Corrections DE :</strong> variables et configuration des arrière-plans de sections, avertissement <code>custom:mod-card</code>, marqueur de débogage des modèles et délai de conservation de 20 secondes.</li><li><strong>Compléments DE/FR :</strong> exemples complets du spark Badge et des directives Broker Badge, Lock et Action Handler. En français, correction de la taille de flèche Tooltip héritée du thème et ajout du contexte de débogage du thème.</li><li><strong>Compléments DE :</strong> ancres YAML, includes, secrets, résultats de fusion et billets vides dans les Foundries ; limitation des états, sections/footers, adaptateurs Background, filtre Map, fusion des événements et More-info intégré. Les positions Lock/Overlay et le rayon de bordure Overlay indiquent les valeurs exactes.</li><li>Le <a href="/projects/uix/translation-review.json">relevé de vérification</a> enregistre les sources et les traductions page par page. Les clés de tableaux, les pages correspondantes et les exemples ajoutés ont été vérifiés. Le build contrôle aussi les liens, médias et métadonnées linguistiques. Les identifiants et les exemples techniques repris gardent leur écriture originale.</li></ul><p>DE/FR restent des traductions rédactionnelles, parfois plus compactes. Cette vérification n’est ni une certification indépendante ni un test d’exécution Home Assistant. Le lien de langue EN continue d’ouvrir la documentation originale dans un nouvel onglet.</p><h2 id="revue-complete-du-22-octobre-2026" tabindex="-1">Revue complète du 22 octobre 2026 <a class="header-anchor" href="#revue-complete-du-22-octobre-2026" aria-label="Permalink to &quot;Revue complète du 22 octobre 2026&quot;">​</a></h2><p>Les <strong>64 pages Markdown canoniques</strong> ont été comparées à la <a href="https://github.com/Lint-Free-Technology/uix/tree/26e54e6d4973231a393933e6479ed1b03cc86cd3/docs/source" target="_blank" rel="noreferrer">révision anglaise figée <code>26e54e6</code></a>. Depuis <code>e2e0701</code>, seules la référence Forge, les Foundries et l’aperçu Forge ont changé ; les 61 autres sources sont identiques. La version stable reste <strong>8.4.0</strong> ; l’aperçu vérifié est <strong>9.0.0-beta.2</strong>.</p><ul><li><strong>EN :</strong> les 64 pages reprennent désormais tout le contenu anglais original plutôt que des espaces réservés. Encadrés, ancres, liens et médias sont adaptés au site, avec attribution CC BY 4.0. Le <a href="/projects/uix/canonical-review.json">manifeste</a> conserve les empreintes des sources et sorties ; les blocs de code sont comparés après normalisation de l’indentation externe, des espaces en fin de ligne et des fins de ligne.</li><li><strong>DE/FR :</strong> ajout des directives Broker Badge, Text content, Lock et Action handler, des ancrages de type Forge, de la base native des Foundries et des badges vides. La version française reçoit les options Tooltip manquantes, le défilement et les valeurs CSS actuelles.</li><li><strong>DE :</strong> correction des exemples Foundry (<code>uix_foundries</code>, <code>foundry</code> racine, <code>forge.billets</code>, type natif, fusion des Sparks, macro <code>returns</code>) et de la FAQ Card-mod jusqu’à 4.2.1. Compléments sur événement navigateur, cache, dépendances, limitation des états, priorité des billets et options CSS des Sparks.</li><li>Chaque page canonique possède un équivalent DE/EN/FR. L’ancien chemin anglais <code>style-custom-panels</code> renvoie vers <code>style-frame-panels</code>. Médias originaux manquants ajoutés ; liens de langue, références et images locales sont vérifiés.</li></ul><p>Cette revue porte sur les sources, le contenu et la documentation. Les traductions DE/FR restent des adaptations rédactionnelles, sans identité ligne par ligne ni certification indépendante. Aucun système HA n’a été appelé ou modifié. Métadonnées stables maintenues en 8.4.0 ; version et révision d’aperçu restent séparées. La comparaison Forge ciblée publiée auparavant est conservée ci-dessous comme historique.</p><h2 id="comparaison-forge-du-22-octobre-2026" tabindex="-1">Comparaison Forge du 22 octobre 2026 <a class="header-anchor" href="#comparaison-forge-du-22-octobre-2026" aria-label="Permalink to &quot;Comparaison Forge du 22 octobre 2026&quot;">​</a></h2><p>La <a href="https://github.com/Lint-Free-Technology/uix/commit/1badf70befb9c9d3d7b06c0eced75af7d552aff1" target="_blank" rel="noreferrer">modification canonique <code>1badf70befb9</code></a> sur <code>dev</code> ajoute la disponibilité de l’éditeur visuel Forge dès <strong>9.0.0-beta.2</strong>. La section correspondante manquait sur nos pages. Un résumé comparé à la source est désormais disponible en <strong>DE/EN/FR</strong> : Native, Forge, Element, Foundry et Export, ainsi que <code>element_base</code>/<code>element</code>, ancrages de type, null/désactivation et limites YAML.</p><p>La page Forge anglaise n’est plus un emplacement réservé pour cette section. La référence canonique complète reste liée. Il ne s’agit pas d’une nouvelle traduction intégrale de toutes les pages UIX ni de tous les changements de <code>dev</code>. Base stable, métadonnées et pied de page restent inchangés ; la comparaison générale antérieure jusqu’à 9.0.0-beta.0 est distincte de cette comparaison ciblée. Modification documentaire sans installation HA ni test d’exécution.</p><h2 id="comparaison-du-9-octobre-2026-base-stable-8-4-0-apercu-9-0-0-beta-0" tabindex="-1">Comparaison du 9 octobre 2026 : base stable 8.4.0, aperçu 9.0.0-beta.0 <a class="header-anchor" href="#comparaison-du-9-octobre-2026-base-stable-8-4-0-apercu-9-0-0-beta-0" aria-label="Permalink to &quot;Comparaison du 9 octobre 2026 : base stable 8.4.0, aperçu 9.0.0-beta.0&quot;">​</a></h2><p>Les notifications canoniques <code>2db023d236c9</code>, <code>c800e607f23d</code>, <code>9b5858f57678</code> et <code>22f8d93f0131</code> ont été comparées aux pages allemandes et françaises. La branche <code>dev</code> vérifiée est <a href="https://github.com/Lint-Free-Technology/uix/commit/e2e070193b3f77b251dcfe05104a4d791a8e9a03" target="_blank" rel="noreferrer"><code>e2e0701</code></a>, version <strong>9.0.0-beta.0</strong>. La version stable de l&#39;original sur <code>master</code> reste <strong>8.4.0</strong> ; les liens de publication, le pied de page et les métadonnées stables restent associés à cette version.</p><ul><li>Suppression des anciennes mentions bêta pour les règles de directive, l&#39;action Popover, le formulaire, les panneaux d&#39;applications et les polices des thèmes.</li><li>FAQ sur le message de rechargement obligatoire et le rechargement automatique après 60 secondes. La nouvelle conservation des fichiers frontend chargés au démarrage de Home Assistant est présentée comme un aperçu.</li><li>Référence Forge, fonderies et aperçu : <code>element_base</code>, surcouche <code>element</code>, <code>element_disabled_paths</code> locaux, fusion, visibilité native et contextes des modèles. Disponibilité explicitement à partir de <strong>9.0.0-beta.0</strong>, pas de 8.4.0 ni de 8.4.1.</li><li>Animation originale <code>forge-auto-entities.gif</code> de <code>9b5858f57678</code> synchronisée pour DE/FR. La <code>source_revision</code> stable reste inchangée ; la version, la branche et la révision d&#39;aperçu sont enregistrées séparément.</li></ul><h2 id="version-actuelle-uix-8-4-0" tabindex="-1">Version actuelle : UIX 8.4.0 <a class="header-anchor" href="#version-actuelle-uix-8-4-0" aria-label="Permalink to &quot;Version actuelle : UIX 8.4.0&quot;">​</a></h2><ul><li>Comparaison le <strong>8 octobre 2026</strong> avec la version stable <a href="https://github.com/Lint-Free-Technology/uix/releases/tag/v8.4.0" target="_blank" rel="noreferrer"><code>v8.4.0</code></a> du 7 octobre 2026, révision <a href="https://github.com/Lint-Free-Technology/uix/commit/71b8ccd38202257c070ae9970a7aac12a68a6389" target="_blank" rel="noreferrer"><code>71b8ccd</code></a>.</li><li><strong>Home Assistant 2026.10.0 ou ultérieur est requis.</strong></li><li>Aucun changement de <code>docs/source</code> ni de <code>docs/mkdocs.yml</code> entre la révision déjà vérifiée <code>c70d1275f1fb08514291feb4c9181a748408b798</code> et <code>v8.4.0</code>.</li><li>Formulaire, Popover, runtime interne des frames, <code>uix-fonts</code>, images d&#39;entité dans les aperçus de carte et références aux résultats Broker sont couverts. L&#39;option des frames reste expérimentale et désactivée par défaut.</li><li>La <a href="./forge/sparks/badge">référence Badge</a>, auparavant absente, est ajoutée. Les versions française et allemande couvrent désormais les 64 chemins Markdown canoniques, avec une page de statut supplémentaire. La page Badge est une référence compacte avec les tableaux complets des options et variables CSS ; les autres exemples originaux sont liés.</li><li>Vue d&#39;ensemble, pied de page, lien de publication, métadonnées JSON allemandes et <code>llms.txt</code> sont actualisés. Les mentions bêta historiques indiquent les versions d&#39;introduction ; les rapports datés ci-dessous décrivent les vérifications précédentes.</li><li>Ajout de 17 ancres compatibles avec les liens anglais existants : 36 liens internes vers des sections françaises sont rétablis sans modifier leurs titres ni leurs ancres françaises.</li><li>Vérification des sources, de la couverture, de la construction, des liens, des langues et des exemples copiables ; sans nouvelle révision phrase par phrase de toutes les traductions antérieures ni tests d&#39;exécution Home Assistant.</li></ul><h2 id="reference-canonique" tabindex="-1">Référence canonique <a class="header-anchor" href="#reference-canonique" aria-label="Permalink to &quot;Référence canonique&quot;">​</a></h2><p>La <a href="https://uix.lf.technology/" target="_blank" rel="noreferrer">documentation UIX anglaise</a> reste la référence pour la syntaxe, le comportement lié à une version et les nouveaux changements. Certaines pages détaillées peuvent encore nécessiter une vérification éditoriale.</p><h2 id="verification-du-24-septembre-2026" tabindex="-1">Vérification du 24 septembre 2026 <a class="header-anchor" href="#verification-du-24-septembre-2026" aria-label="Permalink to &quot;Vérification du 24 septembre 2026&quot;">​</a></h2><p>La traduction française a été vérifiée avec la version stable UIX <code>8.3.1</code> du 22 septembre 2026, révision <a href="https://github.com/Lint-Free-Technology/uix/commit/add5557c0ee13a98c9fe249bed06d215606f2507" target="_blank" rel="noreferrer"><code>add5557</code></a>. Cette vérification inclut également les révisions documentaires <a href="https://github.com/Lint-Free-Technology/uix/commit/a43f3e2bf03edb808c0ea8d83af426d06626181e" target="_blank" rel="noreferrer"><code>a43f3e2</code></a>, <a href="https://github.com/Lint-Free-Technology/uix/commit/8711f1eb4a2a479a2a43d748c0b26f94b040e87a" target="_blank" rel="noreferrer"><code>8711f1e</code></a> et <a href="https://github.com/Lint-Free-Technology/uix/commit/8c6fb830d75477b30f035323161bac8d41599a78" target="_blank" rel="noreferrer"><code>8c6fb83</code></a>.</p><p>La version 8.3.1 corrige deux problèmes : le Map spark fonctionne de nouveau après les changements de carte de Home Assistant 2026.9.0, et le chargement de Web Awesome est contourné sur les appareils anciens, notamment sous iOS 15. Ces corrections de publication n&#39;ajoutent pas de nouvelle option de configuration.</p><ul><li>La page Extras consacrée au style des panneaux personnalisés dans une iframe a été remplacée par <a href="./extras/style-frame-panels">Styliser les panneaux intégrés dans un frame</a>, qui décrit l&#39;option expérimentale, son activation, les frames prises en charge et la compatibilité des frameworks.</li><li><a href="./using/custom-panels">Panneaux personnalisés</a> distingue désormais les panneaux chargés directement des frames de panneaux et d&#39;applications.</li><li>La nouvelle page <a href="./using/apps">Panneaux d&#39;applications et d&#39;Ingress</a> documente les clés de thème, la résolution des slugs et la portée de <code>uix-app</code>.</li><li>La navigation française et les pages d&#39;aperçu ont été mises à jour, ainsi que l&#39;image d&#39;exemple des panneaux d&#39;applications.</li></ul><p>Selon la documentation canonique, le style des frames d&#39;applications de même origine est disponible à partir de UIX <code>3.4.0-beta.1</code>. L&#39;option expérimentale de style des frames est désactivée par défaut.</p><h2 id="mise-a-jour-du-30-septembre-2026" tabindex="-1">Mise à jour du 30 septembre 2026 <a class="header-anchor" href="#mise-a-jour-du-30-septembre-2026" aria-label="Permalink to &quot;Mise à jour du 30 septembre 2026&quot;">​</a></h2><p>Les pages françaises sur les <a href="./using/entities">entités</a> et les <a href="./using/images">images</a> ont été comparées à la révision documentaire canonique <a href="https://github.com/Lint-Free-Technology/uix/commit/7d7c95acb449c1222d8a338e3d9423f91ff0f2a2" target="_blank" rel="noreferrer"><code>7d7c95a</code></a>. Les parts CSS pour les marqueurs de carte depuis Home Assistant 2026.10.0, <code>hui-map-overview</code> et la restriction aux surcharges propres à une entité ont été ajoutées. La base stable reste UIX <code>8.3.1</code> ; le pied de page indique également les changements documentaires vérifiés jusqu’à UIX <code>8.4.0-beta.3</code>.</p><h2 id="mise-a-jour-de-broker-du-5-octobre-2026" tabindex="-1">Mise à jour de Broker du 5 octobre 2026 <a class="header-anchor" href="#mise-a-jour-de-broker-du-5-octobre-2026" aria-label="Permalink to &quot;Mise à jour de Broker du 5 octobre 2026&quot;">​</a></h2><p>Les pages <a href="./broker/directives#regles-de-la-directive">Directives</a> et <a href="./broker/rules#formulaire-compact-de-donnees-capturees">Règles</a> ont été comparées aux changements de référence <a href="https://github.com/Lint-Free-Technology/uix/commit/105b8cd446ea082553be627530efe8a752d57dec" target="_blank" rel="noreferrer"><code>105b8cd</code></a> et <a href="https://github.com/Lint-Free-Technology/uix/commit/04d8e14b006f24e795997c68191f9fde3652bd22" target="_blank" rel="noreferrer"><code>04d8e14</code></a>. Les références aux résultats <code>@&lt;directive-id&gt;</code>, l’exemple YAML inchangé et la disponibilité à partir de UIX <code>8.4.0-beta.9</code> ont été ajoutés. Ces références sont réservées aux règles de directive. Les pages allemandes correspondantes ont également été mises à jour ; la base stable reste UIX <code>8.3.1</code>.</p><h2 id="prochaine-etape" tabindex="-1">Prochaine étape <a class="header-anchor" href="#prochaine-etape" aria-label="Permalink to &quot;Prochaine étape&quot;">​</a></h2><p>La documentation française sera révisée au fil des prochaines modifications de la documentation canonique.</p><h2 id="verification-du-8-octobre-2026" tabindex="-1">Vérification du 8 octobre 2026 <a class="header-anchor" href="#verification-du-8-octobre-2026" aria-label="Permalink to &quot;Vérification du 8 octobre 2026&quot;">​</a></h2><p>Les changements de la documentation anglaise à la révision <a href="https://github.com/Lint-Free-Technology/uix/commit/c70d1275f1fb08514291feb4c9181a748408b798" target="_blank" rel="noreferrer"><code>c70d1275f1fb</code></a>, branche <code>master</code>, ont été comparés aux versions allemande et française.</p><ul><li>Nouveau <a href="./forge/sparks/form">spark Formulaire</a> : schéma, Markdown, envoi/effacement, densité, variables CSS et valeurs du formulaire dans les actions.</li><li>Nouvelle <a href="./extras/uix-actions#popover">action Popover</a> : cartes, icônes d&#39;en-tête, boutons de pied de page, intégration des formulaires et exemples originaux.</li><li>Broker : <code>block</code> synchrone, ancres des règles, réutilisation de l&#39;état du panneau, référence <code>previous</code> des info-bulles, Promises JavaScript et événements du cycle de vie des styles. Suppression des fonctionnalités futures obsolètes.</li><li>Navigation, aperçus de Forge et FAQ complétés ; six médias originaux nouveaux ou modifiés repris.</li><li>Les changements déjà présents concernant les panneaux intégrés et d&#39;applications ont été comparés à nouveau. Les changements des images d&#39;entité, des marqueurs de carte et des polices des thèmes ont été ajoutés.</li></ul><p>Cette vérification porte sur les changements documentaires signalés. La base stable des métadonnées reste <code>8.3.1</code> ; elle ne constitue pas une révision complète de toutes les pages pour une publication stable ultérieure. Les exemples YAML/JavaScript et les médias du nouveau formulaire et du popover proviennent sans modification de la source anglaise. La construction et la vérification des liens contrôlent la publication, sans tests d&#39;exécution dans Home Assistant.</p>',35)])])}const g=a(r,[["render",n]]);export{m as __pageData,g as default};
